naming-conventions.example:
// Field: _camelCase; Property: PascalCase; Constant: PascalCase
public class OrderProcessor
{
    private const int MaxRetryCount = 3;          // PascalCase constant
    private readonly ILogger<OrderProcessor> _logger;    // _camelCase field
    private readonly IOrderRepository _orderRepository;  // _camelCase field

    public OrderProcessor(
        ILogger<OrderProcessor> logger,           // camelCase parameter
        IOrderRepository orderRepository)
    {
        _logger = logger;
        _orderRepository = orderRepository;
    }

    public async Task<Order> GetOrderAsync(int orderId, CancellationToken ct = default)  // PascalCase, Async suffix
    {
        var order = await _orderRepository.GetByIdAsync(orderId, ct);  // camelCase local
        return order ?? throw new NotFoundException($"Order {orderId} not found");
    }
}

var-usage.example:
// Good: type is obvious
var user = new User { Name = "Alice" };
var users = await _repo.GetAllAsync(ct);
var query = from u in users where u.IsActive select u.Name;

// Good: explicit where type is NOT obvious
int count = Convert.ToInt32(Console.ReadLine());
HttpStatusCode status = GetStatusCode(response);

// Good: explicit foreach — the collection name doesn't tell you the element type
foreach (User user in users)
{
    Console.WriteLine(user.Name);
}

async-patterns.example:
// Library code: always ConfigureAwait(false)
public async Task<string> FetchDataAsync(string url, CancellationToken ct)
{
    var response = await _httpClient.GetAsync(url, ct).ConfigureAwait(false);
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync(ct).ConfigureAwait(false);
}

// WRONG: blocks the calling thread; deadlocks in sync-context environments
public string FetchData(string url)
{
    return _httpClient.GetAsync(url).Result.Content.ReadAsStringAsync().Result;
}

// WRONG: async DI factory causes deadlock
services.AddSingleton(sp =>
{
    return sp.GetRequiredService<IBarService>().GetBarAsync().Result; // deadlock
});

// RIGHT: resolve synchronously; do async work after construction
services.AddSingleton<IFooService, FooService>();
// Then in a hosted service or middleware, call InitializeAsync() explicitly

di-guidelines.example:
// Captive dependency — WRONG: singleton holds a scoped DbContext
services.AddSingleton<IReportService, ReportService>();  // singleton
services.AddScoped<AppDbContext>();                       // scoped — captured by singleton

// Fix: inject IServiceScopeFactory and create a scope manually
public class ReportService : IReportService
{
    private readonly IServiceScopeFactory _scopeFactory;

    public ReportService(IServiceScopeFactory scopeFactory)
        => _scopeFactory = scopeFactory;

    public async Task<Report> GenerateAsync(CancellationToken ct)
    {
        await using var scope = _scopeFactory.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        return await db.Reports.FirstOrDefaultAsync(ct);
    }
}

ef-core-performance.example:
// WRONG: loads full entity when only Url is needed
await foreach (var blog in context.Blogs.ToListAsync())
    Console.WriteLine(blog.Url);  // fetches all columns

// RIGHT: project to only what you need
var urls = await context.Blogs
    .AsNoTracking()
    .Select(b => b.Url)
    .ToListAsync(ct);

// WRONG: N+1 — lazy loading fires one query per blog
foreach (var blog in blogs)
    foreach (var post in blog.Posts)   // each access = a separate query
        Console.WriteLine(post.Title);

// RIGHT: eager load in one query
var blogs = await context.Blogs
    .AsNoTracking()
    .Include(b => b.Posts)
    .ToListAsync(ct);

// Bulk update without loading entities (EF Core 7+)
await context.Orders
    .Where(o => o.Status == OrderStatus.Pending && o.CreatedAt < cutoff)
    .ExecuteUpdateAsync(s => s.SetProperty(o => o.Status, OrderStatus.Expired), ct);

// Bulk delete
await context.AuditLogs
    .Where(a => a.CreatedAt < cutoff)
    .ExecuteDeleteAsync(ct);

// Paginate: keyset is faster than Skip for large tables
var page = await context.Orders
    .AsNoTracking()
    .Where(o => o.Id > lastSeenId)
    .OrderBy(o => o.Id)
    .Take(50)
    .Select(o => new OrderSummary(o.Id, o.Total, o.Status))
    .ToListAsync(ct);

